@AllArgsConstructor
public enum WhitelistEntry
{
	SAILING_CORPSES(
		DontTelegrabConfig::isWhitelistSailingCorpses,
		List.of(
			// Birds
			NpcID.SAILING_TERN_DEAD, NpcID.SAILING_OSPREY_DEAD, NpcID.SAILING_FRIGATEBIRD_DEAD, NpcID.SAILING_ALBATROSS_DEAD,
			// Mammals
			NpcID.SAILING_DOLPHIN_DEAD, NpcID.SAILING_SEA_MOGRE_DEAD, NpcID.SAILING_SEA_MOGRE_DEAD_F, NpcID.SAILING_NARWHAL_DEAD, NpcID.SAILING_ORCA_DEAD,
			// Krakens
			NpcID.SAILING_PYGMY_KRAKEN_DEAD, NpcID.SAILING_SPINED_KRAKEN_DEAD, NpcID.SAILING_ARMOURED_KRAKEN_DEAD, NpcID.SAILING_VAMPYRE_KRAKEN_DEAD, NpcID.SAILING_VEILED_KRAKEN_DEAD,
			// Sharks
			NpcID.SAILING_BULL_SHARK_DEAD, NpcID.SAILING_HAMMERHEAD_SHARK_DEAD, NpcID.SAILING_TIGER_SHARK_DEAD, NpcID.SAILING_GREAT_WHITE_SHARK_DEAD,
			// Rays
			NpcID.SAILING_EAGLE_RAY_DEAD, NpcID.SAILING_BUTTERFLY_RAY_DEAD, NpcID.SAILING_STINGRAY_DEAD, NpcID.SAILING_MANTA_RAY_DEAD
		)
	),
	SAILING_CRATES(
		DontTelegrabConfig::isWhitelistSailingCrates,
		List.of(
			NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_WOOD,
			NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_OAK,
			NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_TEAK,
			NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_MAHOGANY,
			NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CAMPHOR,
			NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_IRONWOOD
		)
	),
	MAZE_GUARDIAN(
		DontTelegrabConfig::isWhitelistMazeGuardian,
		List.of(NpcID.MAGICTRAINING_GUARD_MAZE_INCOMPLETE)
	),
	KINGS_RANSOM_GUARD(
		DontTelegrabConfig::isWhitelistKingsRansomGuard,
		List.of(NpcID.KR_KEEP_GUARD_HAIR)
	),
	HUNTER_GOATS(
		DontTelegrabConfig::isWhitelistHunterGoats,
		// TODO: Gamevals
		List.of(16298)
	),
	;

	private final Function<DontTelegrabConfig, Boolean> isEnabled;
	@Getter
	private final List<Integer> ids;

	public boolean isEnabled(DontTelegrabConfig config)
	{
		return isEnabled.apply(config);
	}
}

package com.github.ldavid432;

import static com.github.ldavid432.DontTelegrabConfig.CUSTOM_WHITELIST_KEY;
import static com.github.ldavid432.DontTelegrabConfig.VERSION_KEY;
import static com.github.ldavid432.Whitelist.joinCustomWhitelist;
import static com.github.ldavid432.Whitelist.splitCustomWhitelist;
import com.google.inject.Provides;
import java.awt.Color;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;

@Slf4j
@PluginDescriptor(
	name = "Don't Telegrab NPCs",
	description = "Disables casting telegrab on NPCs",
	tags = {"telekinetic", "grab", "npc", "monster", "no", "telegrab", "block", "sailing"}
)
public class DontTelegrabPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private DontTelegrabConfig config;

	@Inject
	private Whitelist whitelist;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Override
	protected void startUp() throws Exception
	{
		if (config.getVersion() < 1)
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				// Migrate from custom list only to list + configs - basically just remove anything in a config from the list
				List<String> customWhitelist = whitelist.getCustomWhitelist();
				List<String> legacyWhitelist = splitCustomWhitelist(Whitelist.LEGACY_NPC_CONFIG_NAMES);

				List<String> newWhitelist = customWhitelist.stream()
					.filter(npc -> legacyWhitelist.stream().noneMatch(entry -> entry.equalsIgnoreCase(npc)))
					.collect(Collectors.toList());

				configManager.setConfiguration(DontTelegrabConfig.GROUP, CUSTOM_WHITELIST_KEY, joinCustomWhitelist(newWhitelist));

				chatMessageManager.queue(
					QueuedMessage.builder()
						.type(ChatMessageType.CONSOLE)
						.runeLiteFormattedMessage(
							ColorUtil.wrapWithColorTag("Don't Telegrab NPCs has been updated!<br>", Color.RED) +
								ColorUtil.wrapWithColorTag("* Pre-populated whitelist items have been moved into their own config toggles.<br>", Color.RED) +
								ColorUtil.wrapWithColorTag("* Brings newly whitelisted NPCs to users who installed the plugin before they were added.", Color.RED)
						).build()
				);
			}

			configManager.setConfiguration(DontTelegrabConfig.GROUP, VERSION_KEY, 1);
		}

		whitelist.refreshWhiteList();
	}

	// Based on https://github.com/oohwooh/no-use-players/blob/master/src/main/java/com/oohwooh/NoUsePlayerPlugin.java
	@Subscribe
	public void onClientTick(ClientTick clientTick)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.isMenuOpen() || !client.isWidgetSelected())
		{
			return;
		}

		final Widget selectedWidget = client.getSelectedWidget();
		if (selectedWidget == null || selectedWidget.getId() != InterfaceID.MagicSpellbook.TELEGRAB)
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] menuEntries = menu.getMenuEntries();

		MenuEntry[] newEntries = Arrays.stream(menuEntries)
			.filter(entry -> entry.getType() != MenuAction.WIDGET_TARGET_ON_NPC || (entry.getNpc() != null && whitelist.isInWhitelist(entry.getNpc())))
			.toArray(MenuEntry[]::new);

		menu.setMenuEntries(newEntries);
	}

	@Provides
	DontTelegrabConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DontTelegrabConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (DontTelegrabConfig.GROUP.equals(event.getGroup()))
		{
			whitelist.refreshWhiteList();
		}
	}

}

package com.github.ldavid432;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;

@Singleton
public class Whitelist
{
	private final List<Integer> whitelistedIds = new ArrayList<>();
	private final List<String> whitelistedNames = new ArrayList<>();

	@Inject
	private DontTelegrabConfig config;

	public void refreshWhiteList()
	{
		clearWhitelist();

		whitelistedNames.addAll(getCustomWhitelist());

		for (WhitelistEntry entry : WhitelistEntry.values())
		{
			if (entry.isEnabled(config))
			{
				whitelistedIds.addAll(entry.getIds());
			}
		}
	}

	public void clearWhitelist()
	{
		whitelistedIds.clear();
		whitelistedNames.clear();
	}

	public boolean isInWhitelist(final NPC npc)
	{
		return isNameWhitelisted(npc.getName()) || isIdWhitelisted(npc.getId());
	}

	private boolean isNameWhitelisted(String name)
	{
		return name != null && whitelistedNames.stream()
			.anyMatch(whitelistedName -> Text.removeTags(name).equalsIgnoreCase(whitelistedName));
	}

	private boolean isIdWhitelisted(Integer id)
	{
		return id != null && whitelistedIds.contains(id);
	}

	public List<String> getCustomWhitelist()
	{
		return splitCustomWhitelist(config.whitelistedNpcs());
	}

	public static List<String> splitCustomWhitelist(String list)
	{
		return List.of(list.split(" *, *"));
	}

	public static String joinCustomWhitelist(List<String> list)
	{
		return String.join(", ", list);
	}

	public static final String LEGACY_NPC_CONFIG_NAMES = "Maze Guardian, " +
		// Sailing birds
		"Tern, Osprey, Frigatebird, Albatross, " +
		// Sailing mammals
		"Dolphin, Mogre, Narwhal, Orca, " +
		// Sailing krakens
		"Pygmy kraken, Spined kraken, Armoured kraken, Vampyre kraken, Veiled kraken, " +
		// Sailing sharks
		"Bull shark, Hammerhead shark, Tiger shark, Great white shark, " +
		// Sailing rays
		"Eagle Ray, Butterfly Ray, Stingray, Manta ray, " +
		// Sailing crates
		"Lost wooden crate, Lost oak crate, Lost teak crate, Lost mahogany crate, Lost camphor crate, Lost ironwood crate, " +
		// Bug in original whitelist added these without a comma
		"Manta rayLost wooden crate";

}
